//! Anonymous-cashier signing-key settings (支付中心 → 支付设置 → 收银台密钥).
//!
//! The anonymous cashier is authorized by an HMAC capability token, not by a
//! session. The signing secret is generated by the payment center and stored
//! here **encrypted** with the deployment key-encryption key
//! (`SDKWORK_COMMERCE_CASHIER_TOKEN_SECRET`):
//!
//! ```text
//! wrap_key = HKDF(KEK, "tenant={tenant};purpose=cashier-token-secret")
//! signing_key = HKDF(secret, "tenant={tenant};[epoch={n};]purpose=cashier-token")
//! ```
//!
//! A database dump without the deployment KEK cannot recover the signing
//! secret, and a read-only database account cannot mint cashier tokens. The
//! payment center rotates the secret (and the tenant key epoch) without a
//! restart; the previous secret stays valid for a short grace window so links
//! issued just before a rotation keep working.
//!
//! Resolution order for reads: exact tenant row -> platform `'0'` row. A row
//! without a stored secret is a legacy epoch-only row, and callers then report
//! that no signing material exists — there is no deployment-secret signing
//! fallback. Rotation always writes the exact tenant row.
//!
//! The KEK is deployment state that outlives the sealed rows, so the two can
//! disagree: replacing `SDKWORK_COMMERCE_CASHIER_TOKEN_SECRET` after a secret was
//! sealed makes every stored secret unopenable. That case is never treated as
//! "unconfigured" (which would silently mint a competing key over the tenant's
//! slot), and it never fails an order: verification, reveal and rotation fail
//! closed, while minting degrades to the login-required cashier link and reports
//! the mismatch as an operator-visible error.

use chrono::{DateTime, Duration, Utc};
use std::sync::{Mutex, OnceLock};
use sdkwork_contract_service::CommerceServiceError;
use sdkwork_utils_rust::{
    cashier_signing_key_cipher, cashier_signing_key_provider_id, CashierSigningKeyCipher,
    CashierTokenError,
};
use serde::Serialize;
use sqlx::{Pool, Postgres, Row};
use uuid::Uuid;

use crate::shared::store_error;

/// Tenant scope of the platform-wide fallback setting.
pub const PLATFORM_CASHIER_TOKEN_TENANT_ID: &str = "0";

/// Epoch used when no settings row exists; matches the legacy derivation.
pub const DEFAULT_CASHIER_TOKEN_EPOCH: i64 = 1;

/// How long a rotated-out secret keeps verifying already-issued tokens.
///
/// The capability token TTL is 15 minutes; one hour leaves room for a rotation
/// that races an in-flight checkout without keeping old key material around.
pub const CASHIER_TOKEN_PREVIOUS_SECRET_GRACE_SECONDS: i64 = 60 * 60;

/// Which scope supplied the effective setting.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum CashierTokenSettingSource {
    /// An exact tenant row.
    Tenant,
    /// The platform `'0'` fallback row.
    Platform,
    /// No row at all: the legacy epoch 1 derivation.
    Default,
}

impl CashierTokenSettingSource {
    /// Wire label for the admin read model.
    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Tenant => "tenant",
            Self::Platform => "platform",
            Self::Default => "default",
        }
    }
}

/// Public read model of the cashier-token key setting.
///
/// Deliberately contains no key material: the admin surface only needs to show
/// which epoch is active and when it was rotated.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CashierTokenSettingView {
    /// Tenant scope the setting belongs to.
    pub tenant_id: String,
    /// Active key epoch (>= 1), serialized as an int64 decimal string per
    /// API_SPEC §13.6.
    #[serde(with = "sdkwork_utils_rust::serde_int64")]
    pub key_epoch: i64,
    /// When the epoch was last rotated, RFC 3339 UTC; `None` for a never-rotated
    /// tenant/default.
    pub rotated_at: Option<String>,
    /// Operator that performed the last rotation; empty when unknown.
    pub rotated_by: String,
    /// Last write time, RFC 3339 UTC.
    pub updated_at: Option<String>,
    /// Which scope supplied the effective epoch.
    pub source: CashierTokenSettingSource,
    /// Whether the anonymous cashier is enabled for this scope.
    pub enabled: bool,
    /// Whether a signing secret is stored (the admin UI shows "configured").
    pub signing_key_configured: bool,
    /// SHA-256 fingerprint of the stored signing secret, hex. Empty when no
    /// secret is stored. Safe to expose: it identifies the key for comparison
    /// without revealing it (standard key-management UX).
    pub key_fingerprint: String,
    /// Installed key-encryption provider (`local-file`, future `vault`/`kms`).
    pub key_provider: String,
}

impl CashierTokenSettingView {
    /// The effective "no settings row" answer: epoch 1, default source.
    #[must_use]
    pub fn default_for(tenant_id: &str) -> Self {
        Self {
            tenant_id: tenant_id.trim().to_owned(),
            key_epoch: DEFAULT_CASHIER_TOKEN_EPOCH,
            rotated_at: None,
            rotated_by: String::new(),
            updated_at: None,
            source: CashierTokenSettingSource::Default,
            enabled: true,
            signing_key_configured: false,
            key_fingerprint: String::new(),
            key_provider: cashier_signing_key_provider_id().to_owned(),
        }
    }
}

/// Signing secrets resolved for one tenant scope.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CashierTokenSigningSecrets {
    /// Setting row scope that supplied the secret (`tenant` id or `0`).
    pub scope_tenant_id: String,
    /// Active key epoch carried by new tokens.
    pub key_epoch: i64,
    /// Whether the anonymous cashier is enabled for this scope.
    pub enabled: bool,
    /// Active signing secret bytes.
    pub current_secret: Vec<u8>,
    /// Previous signing secret still accepted during the rotation grace window.
    pub previous_secret: Option<Vec<u8>>,
    /// Unix expiry of [`Self::previous_secret`], when one is still accepted.
    pub previous_expires_at_unix: Option<i64>,
    /// Which scope supplied the secret.
    pub source: CashierTokenSettingSource,
}

/// Loads the effective key epoch for a tenant (tenant row -> platform -> 1).
pub async fn load_cashier_token_epoch_postgres(
    pool: &Pool<Postgres>,
    tenant_id: &str,
) -> Result<i64, CommerceServiceError> {
    Ok(retrieve_cashier_token_setting_postgres(pool, tenant_id)
        .await?
        .key_epoch)
}

/// Loads the effective setting view for the admin surface.
pub async fn retrieve_cashier_token_setting_postgres(
    pool: &Pool<Postgres>,
    tenant_id: &str,
) -> Result<CashierTokenSettingView, CommerceServiceError> {
    let tenant_id = normalize_tenant_id(tenant_id);
    if let Some(view) =
        load_cashier_token_setting_row_postgres(pool, &tenant_id, CashierTokenSettingSource::Tenant)
            .await
            .map_err(|error| store_error("failed to load cashier token setting", error))?
    {
        return Ok(view);
    }
    if tenant_id != PLATFORM_CASHIER_TOKEN_TENANT_ID {
        if let Some(view) = load_cashier_token_setting_row_postgres(
            pool,
            PLATFORM_CASHIER_TOKEN_TENANT_ID,
            CashierTokenSettingSource::Platform,
        )
        .await
        .map_err(|error| store_error("failed to load platform cashier token setting", error))?
        {
            return Ok(CashierTokenSettingView { tenant_id, ..view });
        }
    }
    Ok(CashierTokenSettingView::default_for(&tenant_id))
}

/// Loads the signing secrets currently valid for a tenant.
///
/// Returns `None` when no row stores a secret (a legacy epoch-only row or no
/// row at all); callers then fall back to the deployment secret. A row that has
/// a ciphertext but cannot be opened (missing/foreign KEK) fails closed rather
/// than silently dropping back to the deployment secret.
/// How long an opened signing secret stays cached.
///
/// Short enough that an operator fix (restored KEK, rotated secret) takes effect
/// without a restart, long enough to remove the database read and AES open from
/// the checkout hot path.
const CACHED_SIGNING_SECRET_TTL_MILLIS: i64 = 60_000;

/// Upper bound on cached tenants; clearing wholesale is safe because every entry
/// can be reloaded from the database.
const CACHED_SIGNING_SECRET_MAX_ENTRIES: usize = 4096;

#[derive(Clone)]
struct CachedSigningSecrets {
    secrets: CashierTokenSigningSecrets,
    expires_at_millis: i64,
}

static SIGNING_SECRET_CACHE: OnceLock<Mutex<std::collections::HashMap<String, CachedSigningSecrets>>> =
    OnceLock::new();

fn signing_secret_cache(
) -> &'static Mutex<std::collections::HashMap<String, CachedSigningSecrets>> {
    SIGNING_SECRET_CACHE.get_or_init(|| Mutex::new(std::collections::HashMap::new()))
}

fn now_millis() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|elapsed| i64::try_from(elapsed.as_millis()).unwrap_or(i64::MAX))
        .unwrap_or(0)
}

/// Drops the cached secret for one tenant.
///
/// Called by every write that can change the effective secret or its epoch, so a
/// rotation never serves the previous key from memory.
pub fn invalidate_cashier_token_secret_cache(tenant_id: &str) {
    let tenant_id = normalize_tenant_id(tenant_id);
    let mut cache = signing_secret_cache()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    cache.remove(&tenant_id);
}

fn read_cached_signing_secret(tenant_id: &str) -> Option<CashierTokenSigningSecrets> {
    let mut cache = signing_secret_cache()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let now = now_millis();
    match cache.get(tenant_id) {
        Some(entry) if entry.expires_at_millis > now => Some(entry.secrets.clone()),
        Some(_) => {
            cache.remove(tenant_id);
            None
        }
        None => None,
    }
}

fn write_cached_signing_secret(tenant_id: &str, secrets: &CashierTokenSigningSecrets) {
    // A disabled or empty secret is never cached: the next call must re-read so an
    // operator enabling the cashier takes effect immediately.
    if !secrets.enabled || secrets.current_secret.is_empty() {
        return;
    }
    let mut cache = signing_secret_cache()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if cache.len() >= CACHED_SIGNING_SECRET_MAX_ENTRIES {
        cache.clear();
    }
    cache.insert(
        tenant_id.to_owned(),
        CachedSigningSecrets {
            secrets: secrets.clone(),
            expires_at_millis: now_millis() + CACHED_SIGNING_SECRET_TTL_MILLIS,
        },
    );
}

/// Loads the secrets used to *mint* a cashier token, cached per tenant.
///
/// This is the checkout hot path: without the cache every order paid one database
/// read plus one AES-GCM open, so a database hiccup surfaced as "cannot generate
/// the payment QR". Failures are never cached, so a restored KEK recovers at once.
pub async fn cached_mintable_cashier_token_secrets_postgres(
    pool: &Pool<Postgres>,
    tenant_id: &str,
) -> Result<Option<CashierTokenSigningSecrets>, CommerceServiceError> {
    let tenant_id = normalize_tenant_id(tenant_id);
    if let Some(secrets) = read_cached_signing_secret(&tenant_id) {
        return Ok(Some(secrets));
    }
    let loaded = ensure_cashier_token_signing_secrets_postgres(pool, &tenant_id).await?;
    if let Some(secrets) = &loaded {
        write_cached_signing_secret(&tenant_id, secrets);
    }
    Ok(loaded)
}

/// Loads the secrets used to *verify* an already-issued cashier token, cached.
pub async fn cached_cashier_token_signing_secrets_postgres(
    pool: &Pool<Postgres>,
    tenant_id: &str,
) -> Result<Option<CashierTokenSigningSecrets>, CommerceServiceError> {
    let tenant_id = normalize_tenant_id(tenant_id);
    if let Some(secrets) = read_cached_signing_secret(&tenant_id) {
        return Ok(Some(secrets));
    }
    let loaded = load_cashier_token_signing_secrets_postgres(pool, &tenant_id).await?;
    if let Some(secrets) = &loaded {
        write_cached_signing_secret(&tenant_id, secrets);
    }
    Ok(loaded)
}

pub async fn load_cashier_token_signing_secrets_postgres(
    pool: &Pool<Postgres>,
    tenant_id: &str,
) -> Result<Option<CashierTokenSigningSecrets>, CommerceServiceError> {
    load_cashier_token_secret_state_postgres(pool, tenant_id)
        .await?
        .into_required()
}

/// Loads the effective row state for a tenant (exact tenant -> platform `'0'`).
///
/// An exact tenant row stays authoritative even when it is unopenable: falling
/// back to the platform row would sign and verify with a key the tenant never
/// had.
async fn load_cashier_token_secret_state_postgres(
    pool: &Pool<Postgres>,
    tenant_id: &str,
) -> Result<CashierTokenSecretState, CommerceServiceError> {
    let tenant_id = normalize_tenant_id(tenant_id);
    if let Some(row) = load_cashier_token_secret_row_postgres(pool, &tenant_id)
        .await
        .map_err(|error| store_error("failed to load cashier token signing secret", error))?
    {
        // An existing tenant row is authoritative: if it has no stored secret,
        // the tenant has no signing key (no platform inheritance).
        return open_cashier_token_secret_row(row, &tenant_id, CashierTokenSettingSource::Tenant);
    }
    if tenant_id != PLATFORM_CASHIER_TOKEN_TENANT_ID {
        if let Some(row) =
            load_cashier_token_secret_row_postgres(pool, PLATFORM_CASHIER_TOKEN_TENANT_ID)
                .await
                .map_err(|error| {
                    store_error(
                        "failed to load platform cashier token signing secret",
                        error,
                    )
                })?
        {
            return open_cashier_token_secret_row(
                row,
                PLATFORM_CASHIER_TOKEN_TENANT_ID,
                CashierTokenSettingSource::Platform,
            );
        }
    }
    Ok(CashierTokenSecretState::NotStored)
}

/// Loads a tenant's signing secret, provisioning a fresh one on first use.
///
/// A disabled setting never provisions a secret. The generated secret is sealed
/// by the host-installed `CashierSigningKeyCipher`; the deployment KEK is never
/// used as the signing key itself. Callers get `None` when the setting is
/// disabled, when no key provider is available, or when a stored secret cannot
/// be opened with the deployed KEK — minting then falls back to the
/// login-required cashier link while the mismatch is reported as an error.
///
/// An unopenable stored secret is never replaced here: the row is left intact so
/// an operator can restore the original KEK and recover the tenant's key.
pub async fn ensure_cashier_token_signing_secrets_postgres(
    pool: &Pool<Postgres>,
    tenant_id: &str,
) -> Result<Option<CashierTokenSigningSecrets>, CommerceServiceError> {
    let tenant_id = normalize_tenant_id(tenant_id);
    let state = load_cashier_token_secret_state_postgres(pool, &tenant_id).await?;
    match state {
        CashierTokenSecretState::NotStored => {}
        // An opened row yields the tenant key; an unopenable row logs the
        // mismatch and degrades to "no signing material" instead of minting a
        // competing secret over the tenant's occupied key slot.
        state => return Ok(state.into_mintable(&tenant_id)),
    }
    let view = retrieve_cashier_token_setting_postgres(pool, &tenant_id).await?;
    if !view.enabled {
        // A disabled tenant must not auto-provision a secret.
        return Ok(None);
    }
    // No host-installed provider means no anonymous cashier, not a failed order.
    let Ok(cipher) = cashier_signing_key_cipher() else {
        return Ok(None);
    };
    // 64 hex characters from two v4 UUIDs: 32 bytes of CSPRNG material. The
    // deployment KEK is never used as the signing key itself.
    let fresh_secret = format!("{}{}", Uuid::new_v4().simple(), Uuid::new_v4().simple());
    let sealed = match cipher.seal(&tenant_id, fresh_secret.as_bytes()) {
        Ok(sealed) => sealed,
        Err(CashierTokenError::SecretUnavailable) => return Ok(None),
        Err(error) => {
            return Err(CommerceServiceError::storage(format!(
                "failed to seal the initial cashier token signing secret: {error}"
            )))
        }
    };
    // Serialize first-use provisioning across replicas. The advisory lock covers
    // the check-then-insert window, so two processes cannot publish competing
    // secrets; the row lock and `ON CONFLICT ... WHERE secret_ciphertext = ''`
    // guard remain as a second line of defense.
    let mut transaction = pool
        .begin()
        .await
        .map_err(|error| store_error("failed to begin cashier token provisioning", error))?;
    lock_cashier_token_scope(&mut transaction, &tenant_id).await?;
    let existing = load_locked_cashier_token_row(&mut transaction, &tenant_id).await?;
    if existing
        .as_ref()
        .is_some_and(|row| !row.secret_ciphertext.trim().is_empty())
    {
        // Another replica won the provisioning race; use its secret instead.
        transaction
            .commit()
            .await
            .map_err(|error| store_error("failed to commit cashier token provisioning", error))?;
        return load_cashier_token_signing_secrets_postgres(pool, &tenant_id).await;
    }
    let key_epoch = match existing.as_ref() {
        Some(row) => row.key_epoch,
        None => {
            // The platform epoch may have moved between the pre-lock view read
            // and the lock; re-read it under the locked transaction.
            let platform_epoch = if tenant_id != PLATFORM_CASHIER_TOKEN_TENANT_ID {
                load_locked_cashier_token_row(&mut transaction, PLATFORM_CASHIER_TOKEN_TENANT_ID)
                    .await?
                    .map(|row| row.key_epoch)
            } else {
                None
            };
            platform_epoch.unwrap_or(view.key_epoch)
        }
    }
    .max(DEFAULT_CASHIER_TOKEN_EPOCH);
    sqlx::query(
        r#"
        INSERT INTO commerce_payment_cashier_token_setting
            (tenant_id, key_epoch, rotated_at, rotated_by, created_at, updated_at,
             secret_ciphertext, secret_encryption_key_id, secret_encryption_algorithm,
             secret_fingerprint_sha256, secret_updated_at)
        VALUES
            (CAST($1 AS TEXT), $2, NULL, '', NOW(), NOW(), $3, $4, $5, $6, NOW())
        ON CONFLICT (tenant_id) DO UPDATE
        SET secret_ciphertext = EXCLUDED.secret_ciphertext,
            secret_encryption_key_id = EXCLUDED.secret_encryption_key_id,
            secret_encryption_algorithm = EXCLUDED.secret_encryption_algorithm,
            secret_fingerprint_sha256 = EXCLUDED.secret_fingerprint_sha256,
            secret_updated_at = NOW(),
            updated_at = NOW()
        WHERE commerce_payment_cashier_token_setting.secret_ciphertext = ''
        "#,
    )
    .bind(&tenant_id)
    .bind(key_epoch)
    .bind(&sealed.ciphertext)
    .bind(&sealed.encryption_key_id)
    .bind(&sealed.encryption_algorithm)
    .bind(&sealed.fingerprint_sha256)
    .execute(&mut *transaction)
    .await
    .map_err(|error| store_error("failed to provision cashier token signing secret", error))?;
    transaction
        .commit()
        .await
        .map_err(|error| store_error("failed to commit cashier token provisioning", error))?;
    load_cashier_token_signing_secrets_postgres(pool, &tenant_id).await
}

/// Generates and stores a new signing secret for the tenant and returns its view.
///
/// The previous secret (the stored one, or the deployment secret when this is
/// the first rotation) is kept for [`CASHIER_TOKEN_PREVIOUS_SECRET_GRACE_SECONDS`]
/// so tokens minted just before the rotation keep verifying until they expire.
/// A missing KEK fails the rotation instead of silently rotating only the epoch.
pub async fn rotate_cashier_token_secret_postgres(
    pool: &Pool<Postgres>,
    tenant_id: &str,
    rotated_by: &str,
    expected_epoch: Option<i64>,
) -> Result<CashierTokenSettingView, CommerceServiceError> {
    // 64 hex characters from two v4 UUIDs: 32 bytes of CSPRNG material.
    let fresh_secret = format!("{}{}", Uuid::new_v4().simple(), Uuid::new_v4().simple());
    store_cashier_token_secret_postgres(pool, tenant_id, &fresh_secret, rotated_by, expected_epoch)
        .await
}

/// Shortest signing secret an operator may enter by hand.
pub const CASHIER_TOKEN_MANUAL_SECRET_MIN_LEN: usize = 32;
/// Longest signing secret accepted from an operator.
pub const CASHIER_TOKEN_MANUAL_SECRET_MAX_LEN: usize = 512;

/// Validates an operator-supplied signing secret.
///
/// The secret is used verbatim as HMAC key material, so it only has to be long
/// enough and restricted to characters that survive being pasted from a password
/// manager, a `.env` file, or a terminal.
pub fn validate_manual_cashier_token_secret(secret: &str) -> Result<&str, String> {
    let trimmed = secret.trim();
    if trimmed.len() < CASHIER_TOKEN_MANUAL_SECRET_MIN_LEN {
        return Err(format!(
            "the signing key must be at least {CASHIER_TOKEN_MANUAL_SECRET_MIN_LEN} characters"
        ));
    }
    if trimmed.len() > CASHIER_TOKEN_MANUAL_SECRET_MAX_LEN {
        return Err(format!(
            "the signing key must be at most {CASHIER_TOKEN_MANUAL_SECRET_MAX_LEN} characters"
        ));
    }
    if !trimmed
        .bytes()
        .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'+' | b'/' | b'='))
    {
        return Err(
            "the signing key may only contain letters, digits and - _ + / =".to_owned(),
        );
    }
    Ok(trimmed)
}

/// Stores an operator-supplied signing secret and returns the new view.
///
/// Behaves exactly like a rotation — the epoch advances and the replaced secret
/// keeps verifying for the grace window — so manually configuring a key never
/// invalidates links that were scanned moments earlier.
pub async fn set_cashier_token_secret_postgres(
    pool: &Pool<Postgres>,
    tenant_id: &str,
    secret: &str,
    rotated_by: &str,
    expected_epoch: Option<i64>,
) -> Result<CashierTokenSettingView, CommerceServiceError> {
    let secret = validate_manual_cashier_token_secret(secret)
        .map_err(CommerceServiceError::validation)?;
    store_cashier_token_secret_postgres(pool, tenant_id, secret, rotated_by, expected_epoch).await
}

/// Reports the tenant's stored signing secret for operator display.
///
/// Returns `None` when no signing key is stored for the tenant (nothing to
/// reveal) or when the stored secret cannot be opened; the deployment secret is
/// only the key-encryption key, never a signing-key fallback. The `enabled`
/// switch is intentionally ignored here: an operator must still be able to back
/// up or compare the stored key while the anonymous cashier is disabled.
pub async fn reveal_cashier_token_secret_postgres(
    pool: &Pool<Postgres>,
    tenant_id: &str,
) -> Result<Option<CashierTokenSecretReveal>, CommerceServiceError> {
    let Some(secrets) = load_cashier_token_signing_secrets_postgres(pool, tenant_id).await? else {
        return Ok(None);
    };
    let secret = String::from_utf8(secrets.current_secret).map_err(|_| {
        CommerceServiceError::storage("the stored cashier signing secret is not valid UTF-8")
    })?;
    Ok(Some(CashierTokenSecretReveal {
        tenant_id: secrets.scope_tenant_id,
        key_epoch: secrets.key_epoch,
        secret,
        source: secrets.source,
    }))
}

/// The stored signing secret plus the metadata an operator needs to trust it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CashierTokenSecretReveal {
    /// Scope that supplied the secret (`tenant` id or the platform `0`).
    pub tenant_id: String,
    /// Epoch the secret signs under.
    pub key_epoch: i64,
    /// Plaintext signing secret.
    pub secret: String,
    pub source: CashierTokenSettingSource,
}

/// Seals and stores `fresh_secret` as the active signing key.
///
/// Shared by rotation (generated secret) and manual configuration (operator
/// secret) so both paths advance the epoch and retain the replaced secret for the
/// same grace window.
async fn store_cashier_token_secret_postgres(
    pool: &Pool<Postgres>,
    tenant_id: &str,
    fresh_secret: &str,
    rotated_by: &str,
    expected_epoch: Option<i64>,
) -> Result<CashierTokenSettingView, CommerceServiceError> {
    let tenant_id = normalize_tenant_id(tenant_id);
    let cipher = cashier_signing_key_cipher().map_err(CommerceServiceError::storage)?;
    let sealed = cipher
        .seal(&tenant_id, fresh_secret.as_bytes())
        .map_err(|error| {
            CommerceServiceError::storage(format!(
                "failed to seal the rotated cashier token signing secret: {error}"
            ))
        })?;
    let mut transaction = pool
        .begin()
        .await
        .map_err(|error| store_error("failed to begin cashier token rotation", error))?;
    // Serialize rotations and enable/disable changes for the same scope. Lock
    // order is tenant -> platform everywhere, so concurrent rotations cannot
    // compute the same epoch or overwrite each other's previous secret.
    lock_cashier_token_scope(&mut transaction, &tenant_id).await?;
    let tenant_row = load_locked_cashier_token_row(&mut transaction, &tenant_id).await?;
    let platform_row = if tenant_id != PLATFORM_CASHIER_TOKEN_TENANT_ID {
        load_locked_cashier_token_row(&mut transaction, PLATFORM_CASHIER_TOKEN_TENANT_ID).await?
    } else {
        None
    };
    let (previous_ciphertext, previous_key_id, previous_algorithm) =
        effective_previous_ciphertext(
            cipher.as_ref(),
            &tenant_id,
            tenant_row.as_ref(),
            platform_row.as_ref(),
        )?;
    let base_epoch = tenant_row
        .as_ref()
        .map(|row| row.key_epoch)
        .or_else(|| platform_row.as_ref().map(|row| row.key_epoch))
        .unwrap_or(DEFAULT_CASHIER_TOKEN_EPOCH)
        .max(DEFAULT_CASHIER_TOKEN_EPOCH);
    // Optimistic concurrency: the admin rotates the epoch it saw. A double-click,
    // a retried request after an unknown outcome, or two concurrent admins
    // otherwise rotate twice and the second rotation would overwrite the first
    // one's grace secret, invalidating links issued before the first rotation.
    ensure_expected_rotation_epoch(expected_epoch, base_epoch)?;
    let key_epoch = base_epoch.saturating_add(1);
    let previous_expires_at = if previous_ciphertext.is_empty() {
        None
    } else {
        Some(Utc::now() + Duration::seconds(CASHIER_TOKEN_PREVIOUS_SECRET_GRACE_SECONDS))
    };
    sqlx::query(
        r#"
        INSERT INTO commerce_payment_cashier_token_setting
            (tenant_id, key_epoch, rotated_at, rotated_by, created_at, updated_at,
             secret_ciphertext, secret_encryption_key_id, secret_encryption_algorithm,
             secret_fingerprint_sha256, secret_updated_at,
             previous_secret_ciphertext, previous_secret_encryption_key_id,
             previous_secret_encryption_algorithm, previous_secret_expires_at)
        VALUES
            (CAST($1 AS TEXT), $2, NOW(), $3, NOW(), NOW(),
             $4, $5, $6, $7, NOW(), $8, $9, $10, $11)
        ON CONFLICT (tenant_id) DO UPDATE
        SET key_epoch = EXCLUDED.key_epoch,
            rotated_at = EXCLUDED.rotated_at,
            rotated_by = EXCLUDED.rotated_by,
            updated_at = NOW(),
            secret_ciphertext = EXCLUDED.secret_ciphertext,
            secret_encryption_key_id = EXCLUDED.secret_encryption_key_id,
            secret_encryption_algorithm = EXCLUDED.secret_encryption_algorithm,
            secret_fingerprint_sha256 = EXCLUDED.secret_fingerprint_sha256,
            secret_updated_at = NOW(),
            previous_secret_ciphertext = EXCLUDED.previous_secret_ciphertext,
            previous_secret_encryption_key_id = EXCLUDED.previous_secret_encryption_key_id,
            previous_secret_encryption_algorithm = EXCLUDED.previous_secret_encryption_algorithm,
            previous_secret_expires_at = EXCLUDED.previous_secret_expires_at
        "#,
    )
    .bind(&tenant_id)
    .bind(key_epoch)
    .bind(rotated_by.trim())
    .bind(&sealed.ciphertext)
    .bind(&sealed.encryption_key_id)
    .bind(&sealed.encryption_algorithm)
    .bind(&sealed.fingerprint_sha256)
    .bind(&previous_ciphertext)
    .bind(&previous_key_id)
    .bind(&previous_algorithm)
    .bind(previous_expires_at)
    .execute(&mut *transaction)
    .await
    .map_err(|error| store_error("failed to store the rotated cashier token secret", error))?;
    transaction
        .commit()
        .await
        .map_err(|error| store_error("failed to commit cashier token rotation", error))?;
    // The cache must never keep serving a secret a rotation just replaced.
    invalidate_cashier_token_secret_cache(&tenant_id);
    retrieve_cashier_token_setting_postgres(pool, &tenant_id).await
}

/// Enables or disables the anonymous cashier for a tenant and returns the view.
///
/// Disabling stops new minting immediately; tokens already issued remain valid
/// only until their own expiry, because verification reads the same setting.
pub async fn update_cashier_token_enabled_postgres(
    pool: &Pool<Postgres>,
    tenant_id: &str,
    enabled: bool,
) -> Result<CashierTokenSettingView, CommerceServiceError> {
    let tenant_id = normalize_tenant_id(tenant_id);
    let mut transaction = pool
        .begin()
        .await
        .map_err(|error| store_error("failed to begin cashier token setting update", error))?;
    lock_cashier_token_scope(&mut transaction, &tenant_id).await?;
    let tenant_row = load_locked_cashier_token_row(&mut transaction, &tenant_id).await?;
    if tenant_row.is_some() {
        // The row already owns its secret/epoch; only the flag changes.
        sqlx::query(
            "UPDATE commerce_payment_cashier_token_setting \
             SET enabled = $2, updated_at = NOW() \
             WHERE tenant_id = CAST($1 AS TEXT)",
        )
        .bind(&tenant_id)
        .bind(enabled)
        .execute(&mut *transaction)
        .await
        .map_err(|error| store_error("failed to update the cashier token setting", error))?;
    } else {
        // Creating a tenant row must not shadow a platform secret: materialize
        // the effective platform secret (and its rotation grace secret) under
        // this tenant's cipher scope before inserting the row.
        let platform_row = if tenant_id != PLATFORM_CASHIER_TOKEN_TENANT_ID {
            load_locked_cashier_token_row(&mut transaction, PLATFORM_CASHIER_TOKEN_TENANT_ID).await?
        } else {
            None
        };
        let key_epoch = platform_row
            .as_ref()
            .map(|row| row.key_epoch)
            .unwrap_or(DEFAULT_CASHIER_TOKEN_EPOCH)
            .max(DEFAULT_CASHIER_TOKEN_EPOCH);
        let cipher = cashier_signing_key_cipher().map_err(CommerceServiceError::storage)?;
        let materialized =
            materialize_effective_secret_for_tenant(cipher.as_ref(), &tenant_id, platform_row.as_ref())?;
        sqlx::query(
            r#"
            INSERT INTO commerce_payment_cashier_token_setting
                (tenant_id, key_epoch, enabled, created_at, updated_at,
                 secret_ciphertext, secret_encryption_key_id, secret_encryption_algorithm,
                 secret_fingerprint_sha256, secret_updated_at,
                 previous_secret_ciphertext, previous_secret_encryption_key_id,
                 previous_secret_encryption_algorithm, previous_secret_expires_at)
            VALUES
                (CAST($1 AS TEXT), $2, $3, NOW(), NOW(),
                 $4, $5, $6, $7, NOW(), $8, $9, $10, $11)
            ON CONFLICT (tenant_id) DO UPDATE
            SET enabled = EXCLUDED.enabled,
                updated_at = NOW()
            "#,
        )
        .bind(&tenant_id)
        .bind(key_epoch)
        .bind(enabled)
        .bind(&materialized.secret_ciphertext)
        .bind(&materialized.secret_key_id)
        .bind(&materialized.secret_algorithm)
        .bind(&materialized.secret_fingerprint_sha256)
        .bind(&materialized.previous_ciphertext)
        .bind(&materialized.previous_key_id)
        .bind(&materialized.previous_algorithm)
        .bind(materialized.previous_expires_at)
        .execute(&mut *transaction)
        .await
        .map_err(|error| store_error("failed to update the cashier token setting", error))?;
    }
    transaction
        .commit()
        .await
        .map_err(|error| store_error("failed to commit cashier token setting update", error))?;
    // The cache must never keep serving a secret a rotation just replaced.
    invalidate_cashier_token_secret_cache(&tenant_id);
    retrieve_cashier_token_setting_postgres(pool, &tenant_id).await
}

/// Seeds the platform tenant with epoch 1 when the installation has no row.
///
/// Idempotent; safe to call on every startup. A missing row already behaves as
/// epoch 1, so this only makes the "install default" visible in the admin surface.
pub async fn seed_cashier_token_setting_postgres(
    pool: &Pool<Postgres>,
) -> Result<(), CommerceServiceError> {
    sqlx::query(
        r#"
        INSERT INTO commerce_payment_cashier_token_setting (tenant_id, key_epoch)
        VALUES (CAST($1 AS TEXT), 1)
        ON CONFLICT (tenant_id) DO NOTHING
        "#,
    )
    .bind(PLATFORM_CASHIER_TOKEN_TENANT_ID)
    .execute(pool)
    .await
    .map_err(|error| store_error("failed to seed cashier token setting", error))?;
    Ok(())
}

/// Serializes mutations for one cashier-token scope.
///
/// The advisory lock is transaction-scoped and taken in a stable order (tenant,
/// then platform), so concurrent rotations, enable/disable changes, and first-use
/// provisioning for the same tenant cannot interleave their check-then-write
/// sequences. Row locks alone would not cover the "no tenant row yet" race.
async fn lock_cashier_token_scope(
    transaction: &mut sqlx::Transaction<'_, Postgres>,
    tenant_id: &str,
) -> Result<(), CommerceServiceError> {
    sqlx::query("SELECT pg_advisory_xact_lock(hashtext($1)::bigint)")
        .bind(format!("sdkwork.cashier-token:{tenant_id}"))
        .execute(&mut **transaction)
        .await
        .map_err(|error| store_error("failed to lock the cashier token scope", error))?;
    if tenant_id != PLATFORM_CASHIER_TOKEN_TENANT_ID {
        sqlx::query("SELECT pg_advisory_xact_lock(hashtext($1)::bigint)")
            .bind(format!(
                "sdkwork.cashier-token:{PLATFORM_CASHIER_TOKEN_TENANT_ID}"
            ))
            .execute(&mut **transaction)
            .await
            .map_err(|error| {
                store_error("failed to lock the platform cashier token scope", error)
            })?;
    }
    Ok(())
}

/// A cashier-token row locked for update, including the rotation grace columns.
#[derive(Debug)]
struct LockedCashierTokenRow {
    key_epoch: i64,
    secret_ciphertext: String,
    secret_encryption_key_id: String,
    secret_encryption_algorithm: String,
    previous_secret_ciphertext: String,
    previous_secret_encryption_key_id: String,
    previous_secret_encryption_algorithm: String,
    previous_secret_expires_at_unix: Option<i64>,
}

async fn load_locked_cashier_token_row(
    transaction: &mut sqlx::Transaction<'_, Postgres>,
    tenant_id: &str,
) -> Result<Option<LockedCashierTokenRow>, CommerceServiceError> {
    let row = sqlx::query(
        r#"
        SELECT
            key_epoch,
            secret_ciphertext,
            secret_encryption_key_id,
            secret_encryption_algorithm,
            previous_secret_ciphertext,
            previous_secret_encryption_key_id,
            previous_secret_encryption_algorithm,
            EXTRACT(EPOCH FROM previous_secret_expires_at)::BIGINT
                AS previous_secret_expires_at_unix
        FROM commerce_payment_cashier_token_setting
        WHERE tenant_id = CAST($1 AS TEXT)
        FOR UPDATE
        "#,
    )
    .bind(tenant_id)
    .fetch_optional(&mut **transaction)
    .await
    .map_err(|error| store_error("failed to lock the cashier token setting", error))?;
    Ok(row.map(|row| LockedCashierTokenRow {
        key_epoch: row
            .try_get::<i64, _>("key_epoch")
            .unwrap_or(DEFAULT_CASHIER_TOKEN_EPOCH)
            .max(DEFAULT_CASHIER_TOKEN_EPOCH),
        secret_ciphertext: string_cell(&row, "secret_ciphertext"),
        secret_encryption_key_id: string_cell(&row, "secret_encryption_key_id"),
        secret_encryption_algorithm: string_cell(&row, "secret_encryption_algorithm"),
        previous_secret_ciphertext: string_cell(&row, "previous_secret_ciphertext"),
        previous_secret_encryption_key_id: string_cell(
            &row,
            "previous_secret_encryption_key_id",
        ),
        previous_secret_encryption_algorithm: string_cell(
            &row,
            "previous_secret_encryption_algorithm",
        ),
        previous_secret_expires_at_unix: row
            .try_get::<Option<i64>, _>("previous_secret_expires_at_unix")
            .ok()
            .flatten(),
    }))
}

/// Returns the effective current secret sealed under the tenant scope for use as
/// the rotation's previous secret.
fn effective_previous_ciphertext(
    cipher: &dyn CashierSigningKeyCipher,
    tenant_id: &str,
    tenant_row: Option<&LockedCashierTokenRow>,
    platform_row: Option<&LockedCashierTokenRow>,
) -> Result<(String, String, String), CommerceServiceError> {
    let empty = || (String::new(), String::new(), String::new());
    if let Some(row) = tenant_row {
        if row.secret_ciphertext.trim().is_empty() {
            return Ok(empty());
        }
        // Already sealed under this tenant's scope: copy it atomically instead
        // of decrypting and re-encrypting.
        return Ok((
            row.secret_ciphertext.clone(),
            row.secret_encryption_key_id.clone(),
            row.secret_encryption_algorithm.clone(),
        ));
    }
    let Some(row) = platform_row else {
        return Ok(empty());
    };
    if row.secret_ciphertext.trim().is_empty() {
        return Ok(empty());
    }
    // The inherited platform secret is sealed under the platform scope; opening
    // and re-sealing it under the tenant scope keeps the tenant row self-contained.
    let current = cipher
        .open(
            PLATFORM_CASHIER_TOKEN_TENANT_ID,
            &row.secret_ciphertext,
            &row.secret_encryption_key_id,
            &row.secret_encryption_algorithm,
        )
        .map_err(|error| {
            CommerceServiceError::storage(format!(
                "failed to open the inherited cashier token signing secret: {error}"
            ))
        })?;
    let sealed = cipher.seal(tenant_id, &current).map_err(|error| {
        CommerceServiceError::storage(format!(
            "failed to seal the inherited cashier token signing secret: {error}"
        ))
    })?;
    Ok((
        sealed.ciphertext,
        sealed.encryption_key_id,
        sealed.encryption_algorithm,
    ))
}

/// A materialized secret for a newly created tenant row.
#[derive(Debug, Default)]
struct MaterializedCashierSecret {
    secret_ciphertext: String,
    secret_key_id: String,
    secret_algorithm: String,
    secret_fingerprint_sha256: String,
    previous_ciphertext: String,
    previous_key_id: String,
    previous_algorithm: String,
    previous_expires_at: Option<DateTime<Utc>>,
}

/// Re-seals the platform scope's effective secret under a tenant scope.
///
/// Creating a tenant row for an enable/disable flag must not shadow the platform
/// secret the tenant was already using; both the active and the in-grace previous
/// secret are materialized under the tenant scope.
fn materialize_effective_secret_for_tenant(
    cipher: &dyn CashierSigningKeyCipher,
    tenant_id: &str,
    platform_row: Option<&LockedCashierTokenRow>,
) -> Result<MaterializedCashierSecret, CommerceServiceError> {
    let mut materialized = MaterializedCashierSecret::default();
    let Some(row) = platform_row else {
        return Ok(materialized);
    };
    if !row.secret_ciphertext.trim().is_empty() {
        let current = cipher
            .open(
                PLATFORM_CASHIER_TOKEN_TENANT_ID,
                &row.secret_ciphertext,
                &row.secret_encryption_key_id,
                &row.secret_encryption_algorithm,
            )
            .map_err(|error| {
                CommerceServiceError::storage(format!(
                    "failed to open the platform cashier token signing secret: {error}"
                ))
            })?;
        let sealed = cipher.seal(tenant_id, &current).map_err(|error| {
            CommerceServiceError::storage(format!(
                "failed to seal the platform cashier token signing secret for the tenant: {error}"
            ))
        })?;
        materialized.secret_ciphertext = sealed.ciphertext;
        materialized.secret_key_id = sealed.encryption_key_id;
        materialized.secret_algorithm = sealed.encryption_algorithm;
        materialized.secret_fingerprint_sha256 = sealed.fingerprint_sha256;
    }
    let now_unix = Utc::now().timestamp();
    if let Some(expires_at) = row
        .previous_secret_expires_at_unix
        .filter(|expires_at| *expires_at > now_unix)
    {
        if !row.previous_secret_ciphertext.trim().is_empty() {
            let previous = cipher
                .open(
                    PLATFORM_CASHIER_TOKEN_TENANT_ID,
                    &row.previous_secret_ciphertext,
                    &row.previous_secret_encryption_key_id,
                    &row.previous_secret_encryption_algorithm,
                )
                .map_err(|error| {
                    CommerceServiceError::storage(format!(
                        "failed to open the platform previous cashier token signing secret: {error}"
                    ))
                })?;
            let sealed_previous = cipher.seal(tenant_id, &previous).map_err(|error| {
                CommerceServiceError::storage(format!(
                    "failed to seal the platform previous cashier token signing secret for the tenant: {error}"
                ))
            })?;
            materialized.previous_ciphertext = sealed_previous.ciphertext;
            materialized.previous_key_id = sealed_previous.encryption_key_id;
            materialized.previous_algorithm = sealed_previous.encryption_algorithm;
            materialized.previous_expires_at = DateTime::from_timestamp(expires_at, 0);
        }
    }
    Ok(materialized)
}

/// Rejects a rotation whose observed epoch no longer matches.
fn ensure_expected_rotation_epoch(
    expected_epoch: Option<i64>,
    current_epoch: i64,
) -> Result<(), CommerceServiceError> {
    if let Some(expected) = expected_epoch {
        if expected != current_epoch {
            return Err(CommerceServiceError::conflict(
                "cashier token setting changed; reload and retry the rotation",
            ));
        }
    }
    Ok(())
}

/// Raw row carrying both the public metadata and the sealed secret columns.
#[derive(Debug)]
struct CashierTokenSecretRow {
    scope_tenant_id: String,
    key_epoch: i64,
    enabled: bool,
    secret_ciphertext: String,
    secret_encryption_key_id: String,
    secret_encryption_algorithm: String,
    previous_secret_ciphertext: String,
    previous_secret_encryption_key_id: String,
    previous_secret_encryption_algorithm: String,
    previous_secret_expires_at_unix: Option<i64>,
}

/// What one settings row yields when its sealed secret is opened.
///
/// The distinction between [`Self::NotStored`] and [`Self::Unopenable`] is
/// load-bearing: an unopenable row still occupies the tenant's key slot, so
/// provisioning must never treat it as "unconfigured" and mint a competing
/// secret over it.
#[derive(Debug)]
enum CashierTokenSecretState {
    /// An epoch-only row: no signing secret has ever been stored.
    NotStored,
    /// The sealed secret opened under the installed key-encryption key.
    Opened(CashierTokenSigningSecrets),
    /// A secret is stored but the installed key-encryption key cannot open it.
    Unopenable(CashierTokenError),
}

impl CashierTokenSecretState {
    /// Requires an openable secret; an unopenable row fails closed.
    ///
    /// Used by the verification and reveal surfaces: those must refuse to
    /// pretend the deployment holds no key when one is stored and merely
    /// unreadable.
    fn into_required(self) -> Result<Option<CashierTokenSigningSecrets>, CommerceServiceError> {
        match self {
            Self::NotStored => Ok(None),
            Self::Opened(secrets) => Ok(Some(secrets)),
            Self::Unopenable(error) => Err(CommerceServiceError::storage(format!(
                "failed to open the stored cashier token signing secret: {error}"
            ))),
        }
    }

    /// Degrades an unopenable secret to "no signing material".
    ///
    /// Minting is the only caller that can proceed without one: the cashier link
    /// falls back to its login-required form, so a key-encryption key that no
    /// longer matches the sealed rows must not fail the order it only decorates.
    /// The mismatch is still reported as an operator-visible error on every mint,
    /// and verification keeps failing closed through [`Self::into_required`].
    fn into_mintable(self, scope_tenant_id: &str) -> Option<CashierTokenSigningSecrets> {
        match self {
            Self::NotStored => None,
            // A disabled tenant never mints, whatever a row still stores. The
            // check belongs here as well as in the caller so a future caller of
            // `ensure_...` cannot bypass the switch.
            Self::Opened(secrets) if !secrets.enabled => None,
            Self::Opened(secrets) => Some(secrets),
            Self::Unopenable(error) => {
                tracing::error!(
                    tenant_id = scope_tenant_id,
                    error = %error,
                    "stored cashier token signing secret cannot be opened with the deployed \
                     key-encryption key; the anonymous cashier stays unavailable until the \
                     original key is restored"
                );
                None
            }
        }
    }
}

/// Opens the sealed secrets of a row, or reports the row as epoch-only.
fn open_cashier_token_secret_row(
    row: CashierTokenSecretRow,
    scope_tenant_id: &str,
    source: CashierTokenSettingSource,
) -> Result<CashierTokenSecretState, CommerceServiceError> {
    if row.secret_ciphertext.trim().is_empty() {
        return Ok(CashierTokenSecretState::NotStored);
    }
    // A host that installed no provider can open nothing. Reporting it as an
    // unavailable secret keeps every caller's fail-closed path identical instead
    // of surfacing a host-wiring error only some of them handle.
    let Ok(cipher) = cashier_signing_key_cipher() else {
        return Ok(CashierTokenSecretState::Unopenable(
            CashierTokenError::SecretUnavailable,
        ));
    };
    let current_secret = match cipher.open(
        scope_tenant_id,
        &row.secret_ciphertext,
        &row.secret_encryption_key_id,
        &row.secret_encryption_algorithm,
    ) {
        Ok(secret) => secret,
        // Keep the underlying reason (foreign key id vs corrupted ciphertext):
        // it is what tells an operator whether to restore the KEK or rotate.
        Err(error) => return Ok(CashierTokenSecretState::Unopenable(error)),
    };
    let now_unix = Utc::now().timestamp();
    let previous_secret = match row.previous_secret_expires_at_unix {
        Some(expires_at)
            if expires_at > now_unix && !row.previous_secret_ciphertext.trim().is_empty() =>
        {
            // An unopenable rotation leftover authorizes nothing: drop it and end
            // the grace window early instead of failing every checkout that
            // outlives a botched rotation.
            match cipher.open(
                scope_tenant_id,
                &row.previous_secret_ciphertext,
                &row.previous_secret_encryption_key_id,
                &row.previous_secret_encryption_algorithm,
            ) {
                Ok(previous) => Some(previous),
                Err(error) => {
                    tracing::warn!(
                        tenant_id = scope_tenant_id,
                        error = %error,
                        "previous cashier token signing secret is unopenable; the rotation grace \
                         window ends early"
                    );
                    None
                }
            }
        }
        // A previous ciphertext without a future expiry is never accepted; a
        // rotation must not leave an unbounded second key behind.
        _ => None,
    };
    Ok(CashierTokenSecretState::Opened(CashierTokenSigningSecrets {
        scope_tenant_id: row.scope_tenant_id,
        key_epoch: row.key_epoch.max(DEFAULT_CASHIER_TOKEN_EPOCH),
        enabled: row.enabled,
        current_secret,
        previous_secret,
        previous_expires_at_unix: row.previous_secret_expires_at_unix,
        source,
    }))
}

async fn load_cashier_token_setting_row_postgres(
    pool: &Pool<Postgres>,
    tenant_id: &str,
    source: CashierTokenSettingSource,
) -> Result<Option<CashierTokenSettingView>, sqlx::Error> {
    let row = sqlx::query(
        r#"
        SELECT
            tenant_id,
            key_epoch,
            enabled,
            (secret_ciphertext <> '') AS signing_key_configured,
            secret_fingerprint_sha256,
            TO_CHAR(rotated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS rotated_at,
            rotated_by,
            TO_CHAR(updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS updated_at
        FROM commerce_payment_cashier_token_setting
        WHERE tenant_id = CAST($1 AS TEXT)
        LIMIT 1
        "#,
    )
    .bind(tenant_id)
    .fetch_optional(pool)
    .await?;

    Ok(row.map(|row| CashierTokenSettingView {
        tenant_id: string_cell(&row, "tenant_id"),
        key_epoch: row
            .try_get::<i64, _>("key_epoch")
            .unwrap_or(DEFAULT_CASHIER_TOKEN_EPOCH)
            .max(DEFAULT_CASHIER_TOKEN_EPOCH),
        rotated_at: optional_string_cell(&row, "rotated_at"),
        rotated_by: string_cell(&row, "rotated_by"),
        updated_at: optional_string_cell(&row, "updated_at"),
        source,
        enabled: row.try_get::<bool, _>("enabled").unwrap_or(true),
        signing_key_configured: row
            .try_get::<bool, _>("signing_key_configured")
            .unwrap_or(false),
        key_fingerprint: string_cell(&row, "secret_fingerprint_sha256"),
        key_provider: cashier_signing_key_provider_id().to_owned(),
    }))
}

async fn load_cashier_token_secret_row_postgres(
    pool: &Pool<Postgres>,
    tenant_id: &str,
) -> Result<Option<CashierTokenSecretRow>, sqlx::Error> {
    let row = sqlx::query(
        r#"
        SELECT
            tenant_id,
            key_epoch,
            enabled,
            secret_ciphertext,
            secret_encryption_key_id,
            secret_encryption_algorithm,
            previous_secret_ciphertext,
            previous_secret_encryption_key_id,
            previous_secret_encryption_algorithm,
            EXTRACT(EPOCH FROM previous_secret_expires_at)::BIGINT
                AS previous_secret_expires_at_unix
        FROM commerce_payment_cashier_token_setting
        WHERE tenant_id = CAST($1 AS TEXT)
        LIMIT 1
        "#,
    )
    .bind(tenant_id)
    .fetch_optional(pool)
    .await?;

    Ok(row.map(|row| CashierTokenSecretRow {
        scope_tenant_id: string_cell(&row, "tenant_id"),
        key_epoch: row
            .try_get::<i64, _>("key_epoch")
            .unwrap_or(DEFAULT_CASHIER_TOKEN_EPOCH)
            .max(DEFAULT_CASHIER_TOKEN_EPOCH),
        enabled: row.try_get::<bool, _>("enabled").unwrap_or(true),
        secret_ciphertext: string_cell(&row, "secret_ciphertext"),
        secret_encryption_key_id: string_cell(&row, "secret_encryption_key_id"),
        secret_encryption_algorithm: string_cell(&row, "secret_encryption_algorithm"),
        previous_secret_ciphertext: string_cell(&row, "previous_secret_ciphertext"),
        previous_secret_encryption_key_id: string_cell(&row, "previous_secret_encryption_key_id"),
        previous_secret_encryption_algorithm: string_cell(
            &row,
            "previous_secret_encryption_algorithm",
        ),
        previous_secret_expires_at_unix: row
            .try_get::<Option<i64>, _>("previous_secret_expires_at_unix")
            .ok()
            .flatten(),
    }))
}

fn normalize_tenant_id(tenant_id: &str) -> String {
    let trimmed = tenant_id.trim();
    if trimmed.is_empty() {
        PLATFORM_CASHIER_TOKEN_TENANT_ID.to_owned()
    } else {
        trimmed.to_owned()
    }
}

fn string_cell(row: &sqlx::postgres::PgRow, column: &str) -> String {
    row.try_get::<String, _>(column).unwrap_or_default()
}

fn optional_string_cell(row: &sqlx::postgres::PgRow, column: &str) -> Option<String> {
    row.try_get::<Option<String>, _>(column).ok().flatten()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn default_setting_is_epoch_one() {
        let view = CashierTokenSettingView::default_for(" 100001 ");
        assert_eq!(view.tenant_id, "100001");
        assert_eq!(view.key_epoch, 1);
        assert_eq!(view.source, CashierTokenSettingSource::Default);
        assert_eq!(view.source.as_str(), "default");
    }

    #[test]
    fn blank_tenant_uses_the_platform_scope() {
        assert_eq!(normalize_tenant_id("  "), "0");
        assert_eq!(normalize_tenant_id("100001"), "100001");
    }

    #[test]
    fn setting_view_serializes_the_epoch_as_an_int64_string() {
        let view = CashierTokenSettingView::default_for("100001");
        let json = serde_json::to_value(view).expect("setting json");
        assert_eq!(json["keyEpoch"], serde_json::json!("1"));
        assert_eq!(json["source"], serde_json::json!("default"));
    }

    #[test]
    fn an_epoch_only_row_has_no_signing_secret() {
        let row = CashierTokenSecretRow {
            scope_tenant_id: "100001".to_owned(),
            key_epoch: 2,
            enabled: true,
            secret_ciphertext: String::new(),
            secret_encryption_key_id: String::new(),
            secret_encryption_algorithm: String::new(),
            previous_secret_ciphertext: String::new(),
            previous_secret_encryption_key_id: String::new(),
            previous_secret_encryption_algorithm: String::new(),
            previous_secret_expires_at_unix: None,
        };
        assert!(matches!(
            open_cashier_token_secret_row(row, "100001", CashierTokenSettingSource::Tenant),
            Ok(CashierTokenSecretState::NotStored)
        ));
    }

    fn signing_secret(tenant_id: &str) -> CashierTokenSigningSecrets {
        CashierTokenSigningSecrets {
            scope_tenant_id: tenant_id.to_owned(),
            key_epoch: 2,
            enabled: true,
            current_secret: b"tenant-signing-secret".to_vec(),
            previous_secret: None,
            previous_expires_at_unix: None,
            source: CashierTokenSettingSource::Tenant,
        }
    }

    #[test]
    fn the_signing_secret_cache_is_per_tenant_and_invalidatable() {
        invalidate_cashier_token_secret_cache("100001");
        invalidate_cashier_token_secret_cache("100002");
        write_cached_signing_secret("100001", &signing_secret("100001"));
        assert!(read_cached_signing_secret("100001").is_some());
        // A different tenant must never read this secret.
        assert!(read_cached_signing_secret("100002").is_none());
        invalidate_cashier_token_secret_cache("100001");
        assert!(read_cached_signing_secret("100001").is_none());
    }

    #[test]
    fn a_disabled_or_empty_secret_is_never_cached() {
        // Enabling or fixing the setting must take effect on the next call.
        let mut disabled = signing_secret("100003");
        disabled.enabled = false;
        write_cached_signing_secret("100003", &disabled);
        assert!(read_cached_signing_secret("100003").is_none());

        let mut empty = signing_secret("100004");
        empty.current_secret = Vec::new();
        write_cached_signing_secret("100004", &empty);
        assert!(read_cached_signing_secret("100004").is_none());
    }
    #[test]
    fn an_unopenable_stored_secret_fails_closed_for_verification() {
        // Verification, reveal and rotation must never report "no key
        // configured" for a tenant whose key merely cannot be opened.
        let required = CashierTokenSecretState::Unopenable(CashierTokenError::SecretUnavailable)
            .into_required()
            .expect_err("an unopenable secret must fail closed");
        assert!(
            required
                .message()
                .contains("failed to open the stored cashier token signing secret"),
            "unexpected message: {}",
            required.message()
        );
    }

    #[test]
    fn an_unopenable_stored_secret_degrades_minting_instead_of_failing_the_order() {
        // The production failure mode: the deployment KEK was replaced after the
        // tenant signing secret had been sealed. Order checkout must keep working
        // with the login-required cashier link instead of returning a 500.
        let mintable = CashierTokenSecretState::Unopenable(CashierTokenError::SecretUnavailable)
            .into_mintable("100001");
        assert!(mintable.is_none());
    }

    #[test]
    fn an_opened_secret_serves_both_verification_and_minting() {
        let required = CashierTokenSecretState::Opened(signing_secret("100001"))
            .into_required()
            .expect("verification material")
            .expect("stored secret");
        assert_eq!(required.current_secret, b"tenant-signing-secret");
        let mintable = CashierTokenSecretState::Opened(signing_secret("100001"))
            .into_mintable("100001")
            .expect("minting material");
        assert_eq!(mintable.key_epoch, 2);
    }

    #[test]
    fn rotation_epoch_optimistic_check_rejects_a_stale_epoch() {
        assert!(ensure_expected_rotation_epoch(Some(2), 2).is_ok());
        assert!(ensure_expected_rotation_epoch(None, 2).is_ok());
        assert!(ensure_expected_rotation_epoch(Some(1), 2).is_err());
    }

    #[test]
    fn rotation_copies_a_tenant_scoped_previous_secret_without_reencrypting() {
        let cipher = sdkwork_utils_rust::LocalFileCashierSigningKeyCipher::from_key_material(
            vec![42_u8; 64],
        )
        .expect("cipher");
        let sealed = cipher.seal("100001", b"tenant-secret").expect("seal");
        let row = LockedCashierTokenRow {
            key_epoch: 2,
            secret_ciphertext: sealed.ciphertext.clone(),
            secret_encryption_key_id: sealed.encryption_key_id.clone(),
            secret_encryption_algorithm: sealed.encryption_algorithm.clone(),
            previous_secret_ciphertext: String::new(),
            previous_secret_encryption_key_id: String::new(),
            previous_secret_encryption_algorithm: String::new(),
            previous_secret_expires_at_unix: None,
        };
        let (ciphertext, key_id, algorithm) =
            effective_previous_ciphertext(&cipher, "100001", Some(&row), None).expect("previous");
        assert_eq!(ciphertext, sealed.ciphertext);
        assert_eq!(key_id, sealed.encryption_key_id);
        assert_eq!(algorithm, sealed.encryption_algorithm);
    }

    #[test]
    fn platform_previous_secret_is_resealed_under_the_tenant_scope() {
        let cipher = sdkwork_utils_rust::LocalFileCashierSigningKeyCipher::from_key_material(
            vec![43_u8; 64],
        )
        .expect("cipher");
        let sealed = cipher.seal("0", b"platform-secret").expect("seal");
        let platform_row = LockedCashierTokenRow {
            key_epoch: 5,
            secret_ciphertext: sealed.ciphertext.clone(),
            secret_encryption_key_id: sealed.encryption_key_id.clone(),
            secret_encryption_algorithm: sealed.encryption_algorithm.clone(),
            previous_secret_ciphertext: String::new(),
            previous_secret_encryption_key_id: String::new(),
            previous_secret_encryption_algorithm: String::new(),
            previous_secret_expires_at_unix: None,
        };
        let (ciphertext, key_id, algorithm) =
            effective_previous_ciphertext(&cipher, "100001", None, Some(&platform_row))
                .expect("previous");
        let opened = cipher
            .open("100001", &ciphertext, &key_id, &algorithm)
            .expect("open as tenant");
        assert_eq!(opened, b"platform-secret");
        // Re-sealed under the tenant scope, not copied: the platform scope must
        // no longer open it.
        assert!(cipher.open("0", &ciphertext, &key_id, &algorithm).is_err());
    }

    #[test]
    fn enable_toggle_materializes_current_and_previous_under_the_tenant_scope() {
        let cipher = sdkwork_utils_rust::LocalFileCashierSigningKeyCipher::from_key_material(
            vec![44_u8; 64],
        )
        .expect("cipher");
        let current = cipher.seal("0", b"platform-current").expect("seal current");
        let previous = cipher.seal("0", b"platform-previous").expect("seal previous");
        let expires_at = Utc::now().timestamp() + 3600;
        let platform_row = LockedCashierTokenRow {
            key_epoch: 5,
            secret_ciphertext: current.ciphertext.clone(),
            secret_encryption_key_id: current.encryption_key_id.clone(),
            secret_encryption_algorithm: current.encryption_algorithm.clone(),
            previous_secret_ciphertext: previous.ciphertext.clone(),
            previous_secret_encryption_key_id: previous.encryption_key_id.clone(),
            previous_secret_encryption_algorithm: previous.encryption_algorithm.clone(),
            previous_secret_expires_at_unix: Some(expires_at),
        };
        let materialized =
            materialize_effective_secret_for_tenant(&cipher, "100001", Some(&platform_row))
                .expect("materialize");
        assert_eq!(
            cipher
                .open(
                    "100001",
                    &materialized.secret_ciphertext,
                    &materialized.secret_key_id,
                    &materialized.secret_algorithm,
                )
                .expect("open current"),
            b"platform-current"
        );
        assert_eq!(
            cipher
                .open(
                    "100001",
                    &materialized.previous_ciphertext,
                    &materialized.previous_key_id,
                    &materialized.previous_algorithm,
                )
                .expect("open previous"),
            b"platform-previous"
        );
        assert_eq!(
            materialized.previous_expires_at,
            DateTime::from_timestamp(expires_at, 0)
        );
        assert!(!materialized.secret_fingerprint_sha256.is_empty());
    }
}
